in liquidity and partners into recurring global payment flows.","base":"It remains a meaningful stablecoin-specialist chain whose DeFi liquidity stays far below launch peak.","bear":"Incentives fade, validator and bridge decentralization lag, and payment distribution fails to offset liquidity contraction.","most_likely":"base"},"cause_tags":["stablecoin_specialization","capitalized_launch","vertical_integration","token_concentration","retention_risk"],"confidence":"medium"}},"meta":{"dimension_completeness_pct":100,"data_completeness_pct":84,"confidence":"medium","unsourced_fields":["capital.total_raised_usd","capital.later_strategic_round_amount","capital.treasury_usd","team.named_founders","team.regulatory_status","risk.audit_status","risk.archived_sanctions_check","risk.current_external_validator_status","onchain.active_addresses_daily","onchain.dev_activity_monthly","onchain.tvl_concentration"],"last_reviewed":"2026-07-29"}},{"chain":"TON","source_catalog":{"site":{"title":"TON official network site","url":"https://ton.org/en"},"naming":{"title":"TON documentation: official Gram naming","url":"https://docs.ton.org/foundations/whitepapers/overview"},"primer":{"title":"TON official primer and lifecycle history","url":"https://ton.org/primer.pdf"},"foundations":{"title":"TON blockchain foundations","url":"https://docs.ton.org/foundations/overview"},"incident":{"title":"TON December 2023 inscriptions incident technical report","url":"https://ton.org/en/technical-report-december-5-inscriptions-launch-on-ton"},"sec":{"title":"SEC Telegram Gram settlement","url":"https://www.sec.gov/newsroom/press-releases/2020-146"},"token":{"title":"CoinGecko Gram market-data API","url":"https://api.coingecko.com/api/v3/coins/the-open-network"},"tvl":{"title":"DefiLlama TON historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/TON"},"fees":{"title":"DefiLlama TON fees API","url":"https://api.llama.fi/overview/fees/TON?dataType=dailyFees"},"revenue":{"title":"DefiLlama