},{"date":"2024-12","type":"governance","description":"Avery Ching became Aptos Labs CEO.","source_url":"https://aptoslabs.com/"}],"regulatory_status":null},"narrative":{"as_of":"2026-07-29","purpose":"A Move-based, parallel-execution L1 designed for safe, scalable, and upgradeable financial and consumer applications.","positioning":"Aptos translates Meta/Diem engineering into a public L1 centered on Move, Block-STM-style parallel execution, upgradeability, payments, and institutional applications.","competitors":[{"name":"Sui","relationship":"Move-language developer and application competitor"},{"name":"Solana","relationship":"high-throughput trading and payments competitor"},{"name":"performance-oriented EVM L1s","relationship":"liquidity and institutional-deployment alternatives"}],"narrative_arc":"Aptos launched with strong Diem engineering and venture distribution, then shifted toward stablecoin, financial, and institutional throughput while token and DeFi TVL fell sharply from their peaks.","media_sentiment":"mixed"},"risk":{"as_of":"2026-07-29","exploits":[],"sanctions":{"flagged":false,"detail":"No chain-level designation is asserted by this dossier; an archived exact-name SDN review remains an explicit publication gap."},"extraction_flags":["initial_allocation_concentration","token_unlocks","inflationary_staking","stake_weighted_governance","token_value_capture"],"audit_status":null,"risks":[{"type":"allocation_concentration","detail":"The initial community allocation was 51.02%, but the official disclosure says most was initially held by the Foundation and 100M APT by Aptos Labs.","source_url":"https://aptosfoundation.org/currents/aptos-tokenomics-overview"},{"type":"token_unlocks","detail":"Investor and core-contributor allocations follow a four-year schedule ending at the October 2026 mainnet anniversary.","source_url":"https://aptosfoundation.org/currents/aptos-tokenomics-overview"},{"type":"inflation_and_governance","detail":"Staking rewards increase total supply and governance is stake weighted; reward and fee mechanics can be changed through governance.","source_url":"https://aptosfoundation.org/currents/aptos-tokenomics-overview"},{"type":"token_value_capture","detail":"Large stablecoin and DEX flows currently produce much smaller fee totals, so throughput and APT economic capture must be measured separately.","source_url":"https://api.llama.fi/overview/fees/Aptos?dataType=dailyFees"}]},"synthesis":{"as_of":"2026-07-29","situation":"Aptos records $1.25B in stablecoins and $826M in 30-day spot DEX volume, but only $63.0M DeFi TVL and $0.84M in 30-day fees; TVL is 95% below peak and APT is 97% below its all-time high.","postmortem":null,"why":"Aptos persists because its Meta/Diem engineering lineage, Move safety model, parallel execution, and institutional relationships create durable infrastructure and stablecoin distribution despite weak current token capture.","success_mechanism":"Move, parallel execution, upgradeability, and finance-oriented distribution can support high-throughput settlement and institutional applications.","strategic_choices":["Preserve Move and parallel execution instead of adopting EVM compatibility.","Use a large ecosystem allocation and venture-backed operating company to accelerate distribution.","Prioritize stablecoins, payments, institutions, and upgradeable high-throughput infrastructure."],"unknowns":["How much stablecoin flow is durable settlement versus trading or incentive routing.","Current validator and stake concentration, treasury value, and post-October-2026 distribution pressure.","Whether transaction volume can generate materially higher fees or APT value capture."],"lessons_learned":["Stablecoin circulation is not the same measure as app TVL.","High throughput does not guarantee high fee or token value capture.","Initial allocation and staking inflation remain lifecycle inputs years after launch."],"could_differ":"EVM compatibility might have accelerated liquidity portability, while a tighter initial distribution might have reduced overhang, but both would change the project''s core technical and growth strategy.","outlook":{"bull":"Stablecoin and institutional settlement convert into recurring application fees and stronger APT demand.","base":"Aptos remains a technically durable Move L1 with meaningful stablecoin throughput and weak economic capture.","bear":"Unlocks, inflation, and low fee capture overwhelm application and institutional growth.","most_likely":"base"},"cause_tags":["move_vm","parallel_execution","stablecoin_settlement","token_unlocks","value_capture"],"confidence":"high"}},"meta":{"dimension_completeness_pct":100,"data_completeness_pct":87,"confidence":"high","unsourced_fields":["capital.total_raised_usd","capital.treasury_usd","team.regulatory_status","risk.audit_status","risk.archived_sanctions_check","onchain.active_addresses_daily","onchain.dev_activity_monthly","onchain.tvl_concentration","token.contractual_unlock_overhang_pct","synthesis.current_validator_concentration"],"last_reviewed":"2026-07-29"}}]')
),
dossiers AS (
  SELECT value AS dossier FROM dossier_seed, json_each(dossier_seed.payload)
),
dimension_rows AS (
  SELECT
    json_extract(dossier, '$.chain') AS chain,
    dimensions.key AS dimension,
    dimensions.value AS data,
    (SELECT json_group_array(json(json_extract(dossier, '$.source_catalog.' || source_keys.value)))
     FROM json_each(json_extract(dossier, '$.dimension_sources.' || dimensions.key)) AS source_keys) AS sources
  FROM dossiers, json_each(json_extract(dossier, '$.dimensions')) AS dimensions
),
meta_rows AS (
  SELECT
    json_extract(dossier, '$.chain') AS chain,
    '_meta' AS dimension,
    json_extract(dossier, '$.meta') AS data,
    (SELECT json_group_array(json(value))
     FROM json_each(json_extract(dossier, '$.source_catalog'))) AS sources
  FROM dossiers
)
INSERT OR REPLACE INTO chain_facts (chain, dimension, data, sources, updated_at)
SELECT chain, dimension, data, sources, '2026-07-29' FROM dimension_rows
UNION ALL
SELECT chain, dimension, data, sources, '2026-07-29' FROM meta_rows;
